package vn.edu.hcmute.example2;
import java.util.Collection; import org.springframework.security.core.GrantedAuthority; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.UserDetails;
public record AppPrincipal(AppUser user) implements UserDetails { public Collection<? extends GrantedAuthority> getAuthorities(){return java.util.List.of(new SimpleGrantedAuthority("ROLE_"+user.getRole()));} public String getPassword(){return user.getPassword();} public String getUsername(){return user.getUsername();} public boolean isAccountNonExpired(){return true;} public boolean isAccountNonLocked(){return true;} public boolean isCredentialsNonExpired(){return true;} public boolean isEnabled(){return true;} public String getFullName(){return user.getFullName();} public String getImage(){return user.getImage();} }
